<script setup lang="ts">
import { computed,onMounted,ref,watch } from 'vue';
import type { ReplayDocument,StateSnapshot,ReplayEvent } from '../shared/domain/contracts.js';
import { newEventDraft,templateEligibility,type EventDraft } from '../shared/domain/recording.js';
import { copyJson,renderBranch,selectedTemplate,templateKeys,type RoleLibrary } from '../shared/roles/editor-model.js';
import { formatPlayerIdentity } from '../shared/domain/format.js';
import EffectEditor from './EffectEditor.vue';
const props=defineProps<{document:ReplayDocument;state:StateSnapshot;editing?:ReplayEvent;busy:boolean}>();
const emit=defineEmits<{record:[draft:EventDraft];cancel:[]}>();
const draft=ref(newEventDraft(props.document.phases.at(-1)!.phaseId)),library=ref<RoleLibrary>(),libraryError=ref('');
const roleId=ref(''),branchId=ref(''),variantId=ref(''),values=ref<Record<string,string>>({}),customKeys=ref<string[]>([]),custom=ref(false),customText=ref('');
const actionKinds=['自定义','专用能力','拜访','公开宣称','伪装','提名','投票','处决','角色变化','状态变化','获得能力','延迟结算','通知','夜序提示','最终裁决'];
const availableAbilities=computed(()=>props.state.abilities.filter(ability=>!draft.value.playerId||ability.holder.kind==='player'&&ability.holder.playerId===draft.value.playerId));
const frozenTemplate=computed(()=>(props.editing?.action.input.editorDraft as unknown as EventDraft|undefined)?.template);
const selectedRole=computed(()=>frozenTemplate.value?.role.id===roleId.value?frozenTemplate.value.role:library.value?.roles.find(role=>role.id===roleId.value));
const selectedBranch=computed(()=>frozenTemplate.value?.role.id===roleId.value&&frozenTemplate.value?.branch.id===branchId.value?frozenTemplate.value.branch:selectedRole.value?.branches.find(branch=>branch.id===branchId.value));
const eligibility=computed(()=>selectedRole.value?templateEligibility(copyJson(selectedRole.value),props.state.abilities.find(ability=>ability.abilityInstanceId===draft.value.abilityId)?.rule.version):undefined);
const fields=computed(()=>{if(!selectedBranch.value)return [];const keys=templateKeys(selectedTemplate(selectedBranch.value,variantId.value));return selectedBranch.value.fields.filter(field=>keys.includes(field.key));});
const output=computed(()=>selectedBranch.value?renderBranch(selectedBranch.value,values.value,custom.value?customText.value:undefined,customKeys.value,variantId.value):undefined);
const key=computed(()=>`botcreplay-form-${props.document.replayId}`),hasDraft=ref(false);
async function loadLibrary(){try{const response=await fetch('/api/role-library');if(!response.ok)throw Error('配置库读取失败');library.value=await response.json();}catch(error){libraryError.value=(error as Error).message;}}
function reset(){draft.value=newEventDraft(props.document.phases.at(-1)!.phaseId);roleId.value='';branchId.value='';values.value={};customKeys.value=[];custom.value=false;customText.value='';}
watch(()=>props.document.replayId,()=>{reset();hasDraft.value=!!localStorage.getItem(key.value);});
watch(()=>props.document.phases.at(-1)!.phaseId,phase=>{if(!props.editing)draft.value.phaseId=phase;});
watch(()=>draft.value.abilityId,id=>{const ability=props.state.abilities.find(ability=>ability.abilityInstanceId===id);if(ability){roleId.value=ability.rule.roleId;}});
watch(roleId,()=>{branchId.value=selectedRole.value?.branches[0]?.id??'';custom.value=!eligibility.value?.allowed;},{flush:'sync'});
watch(branchId,()=>{variantId.value='';values.value={};customKeys.value=[];for(const field of selectedBranch.value?.fields??[]){const actor=props.state.players.find(player=>player.playerId===draft.value.playerId);values.value[field.key]=/主语|行动者|本人/.test(field.label)&&actor?`${actor.nickname}（${actor.actualRole.name}）${actor.life.actuallyAlive?'':'💀'}`:'';}},{flush:'sync'});
watch(()=>props.editing,event=>{if(!event){reset();return;}const saved=event.action.input.editorDraft as unknown as EventDraft|undefined;if(saved){draft.value=copyJson(saved);const template=saved.template;if(template){roleId.value=template.role.id;branchId.value=template.branch.id;variantId.value=template.variantId;values.value=copyJson(template.values);customKeys.value=[...template.customKeys];custom.value=template.customText!==undefined;customText.value=template.customText??'';}}else{draft.value={...newEventDraft(event.phaseId,event.subject.kind==='player'?event.subject.playerId:''),eventId:event.eventId,action:event.action.name,text:event.customRecords?.find(record=>record.part==='action')?.text??'',information:typeof event.receivedInformation==='string'?event.receivedInformation:JSON.stringify(event.receivedInformation),note:event.note,exceptionReason:event.exceptionReason??'',targetIds:event.targetPlayerIds??[],visibility:event.visibility};}},{immediate:true});
function materialize(){const value=copyJson(draft.value);delete value.template;if(value.action==='专用能力'&&selectedRole.value&&selectedBranch.value)value.template={role:copyJson(selectedRole.value),branch:copyJson(selectedBranch.value),values:copyJson(values.value),customKeys:[...customKeys.value],variantId:variantId.value,...(custom.value||variantId.value==='__custom'?{customText:customText.value}:{}),libraryRevision:library.value?.revision??0};return value;}
watch([draft,values,customKeys,customText,custom,roleId,branchId,variantId],()=>{try{localStorage.setItem(key.value,JSON.stringify(materialize()));hasDraft.value=true;}catch{libraryError.value='录入草稿空间不足，请先保存或复制原文';}},{deep:true});
function restore(){try{const value=JSON.parse(localStorage.getItem(key.value)??'null') as EventDraft;if(!value?.eventId)throw Error();draft.value=value;const template=value.template;if(template){roleId.value=template.role.id;branchId.value=template.branch.id;variantId.value=template.variantId;values.value=template.values;customKeys.value=template.customKeys;custom.value=template.customText!==undefined;customText.value=template.customText??'';}}catch{libraryError.value='录入草稿无法恢复';}}
function submit(){emit('record',materialize());}
function clear(){localStorage.removeItem(key.value);reset();hasDraft.value=false;}
defineExpose({clear});
onMounted(()=>{hasDraft.value=!!localStorage.getItem(key.value);void loadLibrary();});
</script>
<template>
 <section class="panel record-composer" aria-label="事件录入"><h2>{{editing?'修订先前记录':'新建记录'}}</h2><p v-if="libraryError" role="alert">{{libraryError}}</p>
 <div class="toolbar"><button v-if="hasDraft&&!editing" @click="restore">恢复录入草稿</button><button @click="loadLibrary">刷新本地填写配置</button><button @click="clear">清空表单</button></div>
 <div class="form-grid"><label>记录阶段<select v-model="draft.phaseId" aria-label="记录阶段"><option v-for="phase in document.phases" :key="phase.phaseId" :value="phase.phaseId">{{phase.kind==='preparation'?'准备':`第${phase.number}${phase.kind==='night'?'夜':'天'}`}}</option></select></label><label>实际行动者<select v-model="draft.playerId" aria-label="实际行动者"><option value="">说书人</option><option v-for="player in state.players" :key="player.playerId" :value="player.playerId">{{player.seat}}号 {{player.nickname}} · {{formatPlayerIdentity(player,state)}}</option></select></label><label>记录类型<select v-model="draft.action" aria-label="记录类型"><option v-for="kind in actionKinds" :key="kind">{{kind}}</option></select></label><label>公开 / 私下<select v-model="draft.visibility"><option value="storyteller">说书人</option><option value="private">私下</option><option value="public">公开</option></select></label></div>
 <label>本次能力实例（可不关联）<select v-model="draft.abilityId" aria-label="本次能力实例"><option value="">人工 / 通用记录</option><option v-for="ability in availableAbilities" :key="ability.abilityInstanceId" :value="ability.abilityInstanceId">{{ability.rule.roleName??ability.rule.roleId}} · {{ability.mode==='perceived'?'认知':'真实'}} · {{ability.usage.state}} · {{ability.abilityInstanceId}}</option></select></label>
 <fieldset class="target-options"><legend>选择的玩家（可包含死亡玩家）</legend><label v-for="player in state.players" :key="player.playerId"><input type="checkbox" v-model="draft.targetIds" :value="player.playerId">{{player.seat}}号 {{player.nickname}}{{player.life.actuallyAlive?'':' 💀'}}</label></fieldset>
 <div v-if="draft.action==='专用能力'" class="template-editor"><div class="form-grid"><label>填写模板角色<select v-model="roleId" aria-label="填写模板角色"><option value="">请选择角色</option><option v-for="role in library?.roles.filter(role=>role.enabled)" :key="role.id" :value="role.id">{{role.name}}{{role.origin==='custom'?' · 本地自定义':''}}</option></select></label><label>记录分支<select v-model="branchId" aria-label="记录分支"><option v-for="branch in selectedRole?.branches" :key="branch.id" :value="branch.id">{{branch.name}}</option></select></label></div>
 <p class="muted">{{eligibility?.reason}}</p><p v-if="selectedBranch" class="muted">时点：{{selectedBranch.timing}} · {{selectedBranch.notes}}</p><div class="toolbar"><button @click="custom=false" :disabled="!eligibility?.allowed">按字段填写</button><button @click="custom=true">自定义</button></div>
 <template v-if="selectedBranch"><label v-if="!custom&&selectedBranch.variants?.length">结果句式<select v-model="variantId" aria-label="结果句式"><option value="">{{selectedBranch.templateLabel??'默认句式'}}</option><option v-for="variant in selectedBranch.variants" :key="variant.id" :value="variant.id">{{variant.label}}</option><option value="__custom">自定义</option></select></label><label v-if="custom||variantId==='__custom'">自定义原文<textarea v-model="customText" aria-label="专用自定义原文"></textarea></label>
 <div v-else class="form-grid"><label v-for="field in fields" :key="field.id">{{field.label}}{{field.required?' *':''}}<span class="muted">{{field.help}}</span><select v-if="field.kind==='select'&&!customKeys.includes(field.key)" v-model="values[field.key]" :aria-label="'填写'+field.label"><option value="">请选择</option><option v-for="option in field.options" :key="option">{{option}}</option></select><textarea v-else-if="field.kind==='textarea'" v-model="values[field.key]" :aria-label="'填写'+field.label"></textarea><input v-else v-model="values[field.key]" :list="field.kind==='players'?'record-player-names':field.kind==='role'?'record-role-names':undefined" :aria-label="'填写'+field.label" :type="field.kind==='number'&&!customKeys.includes(field.key)?'number':'text'"><button type="button" @click="customKeys.includes(field.key)?customKeys.splice(customKeys.indexOf(field.key),1):customKeys.push(field.key)">{{customKeys.includes(field.key)?'使用字段类型':'自定义此项'}}</button></label></div><pre class="record-preview" data-testid="event-preview">{{custom||variantId==='__custom'?customText:output?.text}}</pre></template>
 </div>
 <label v-else>记录原文 / 自定义<textarea v-model="draft.text" aria-label="记录原文" rows="3" placeholder="原文、换行和emoji都会保存；通用行为也始终可自定义"></textarea></label>
 <datalist id="record-player-names"><option v-for="player in state.players" :key="player.playerId" :value="`${player.nickname}（${player.actualRole.name}）${player.life.actuallyAlive?'':'💀'}`"/></datalist><datalist id="record-role-names"><option v-for="role in document.script.roles" :key="role.role.roleId" :value="role.role.name"/></datalist>
 <label>实际收到的信息（与真实后果分别记录）<textarea v-model="draft.information" aria-label="实际收到的信息"></textarea></label>
 <div v-if="draft.action==='投票'" class="form-grid"><label>总票数<input v-model.number="draft.voteTotal" type="number" min="0" step="1" aria-label="总票数"></label><label>个人票 / 技能补录（可选）<textarea v-model="draft.voteDetails" aria-label="个人票补录" placeholder="例如恶魔是否投票、管家及主人、特殊票权"></textarea></label></div>
 <div v-if="draft.action==='角色变化'||draft.effects.some(effect=>effect.kind==='role')" class="form-grid"><label>换角形式<select v-model="draft.roleChangeKind"><option value="replacement">替换角色</option><option value="exchange">双方交换</option></select></label><label>实际结果状态<select v-model="draft.roleChangeStatus"><option value="applied">已实际生效（须完整映射）</option><option value="selected">仅选择，结果待填</option><option value="failed">本次未生效</option><option value="not-used">未使用</option></select></label></div>
 <EffectEditor v-model="draft.effects" :document="document" :state="state" :player-id="draft.playerId" />
 <details><summary>因果来源、换角来源及关联后果</summary><div class="form-grid"><label>来源事件<select v-model="draft.sourceEventId" aria-label="来源事件"><option value="">无</option><option v-for="event in document.events.filter(event=>event.eventId!==editing?.eventId)" :key="event.eventId" :value="event.eventId">{{event.action.name}} · {{event.eventId.slice(0,12)}}</option></select></label><label>触发时提供能力的玩家<select v-model="draft.sourcePlayerId" aria-label="来源玩家"><option value="">不指定</option><option v-for="player in state.players" :key="player.playerId" :value="player.playerId">{{player.seat}}号 {{player.nickname}}</option></select></label><label>引用既有后果（只展示，不重复应用）<select v-model="draft.relatedEffectIds" multiple><option v-for="effect in document.events.flatMap(event=>event.effects)" :key="effect.effectId" :value="effect.effectId">{{effect.kind}} · {{effect.effectId}}</option></select></label></div></details>
 <label>备注 / 通知说明<textarea v-model="draft.note" aria-label="记录备注"></textarea></label><label>特殊裁决依据（常规约束例外时必填）<textarea v-model="draft.exceptionReason" aria-label="特殊裁决依据"></textarea></label>
 <div class="toolbar"><button @click="submit" :disabled="busy">{{editing?'预览修订影响':'保存本条记录'}}</button><button v-if="editing" @click="emit('cancel')">取消修订</button></div><p class="muted">未通过当前完整方案的内置模板保留自定义入口。事实、收到信息和显式后果分别保存；保存后可继续修订。</p>
 </section>
</template>
